# CDR MILP for Railway Rescheduling under ETCS Level 2 DTG Signalling
# Enhanced RECIFE-MILP model — Python implementation using PuLP

```python
import pulp

def build_cdr_milp(
    trains,                 # list of train ids
    resources,              # list of resource ids (block/TDS sections)
    switch_resources,       # subset of resources that are switches
    routes,                 # {t: ordered list of resources on route of t}
    a0,                     # {(t,r): scheduled entry time}
    d0,                     # {(t,r): scheduled exit time}
    running_times,          # {(t,r,p): delta_{t,r,p}}
    braking_times,          # {(t,r,p): b_{t,r,p}} approach time before r
    initial_delay,          # {t: initial delay at start}
    priority_weights,       # {t: w_t}
    min_dwell,              # {(t,r): minimum dwell time (optional, default 0)}
    headway,                # {r: minimum separation h_r on switch resources}
    H,                      # time horizon (minutes)
    profile_options,        # {t: list of speed profile options p}
):
    """
    Build and solve the CDR MILP.
    Returns the solved PuLP model.
    """
    M = H  # big-M
    times = range(0, H + 1)

    prob = pulp.LpProblem("CDR_ETCS2_DTG", pulp.LpMinimize)

    # ---------------- Decision variables ----------------
    a = {}   # entry times
    d = {}   # exit times
    for t in trains:
        for r in routes[t]:
            a[t, r] = pulp.LpVariable(f"a_{t}_{r}", 0, H, pulp.LpContinuous)
            d[t, r] = pulp.LpVariable(f"d_{t}_{r}", 0, H, pulp.LpContinuous)

    x = {}   # speed profile choice
    for t in trains:
        for r in routes[t]:
            for p in profile_options[t]:
                x[t, r, p] = pulp.LpVariable(f"x_{t}_{r}_{p}", cat="Binary")

    y = {}   # occupancy at discrete time theta
    for t in trains:
        for r in routes[t]:
            for theta in times:
                y[t, r, theta] = pulp.LpVariable(f"y_{t}_{r}_{theta}", cat="Binary")

    z = {}   # conflict indicators
    for i, t in enumerate(trains):
        for t2 in trains[i + 1:]:
            shared = set(routes[t]) & set(routes[t2])
            for r in shared:
                for theta in times:
                    z[t, t2, r, theta] = pulp.LpVariable(
                        f"z_{t}_{t2}_{r}_{theta}", cat="Binary")

    s = {}   # ordering variables
    for i, t in enumerate(trains):
        for t2 in trains[i + 1:]:
            shared = set(routes[t]) & set(routes[t2])
            for r in shared:
                s[t, t2, r] = pulp.LpVariable(f"s_{t}_{t2}_{r}", cat="Binary")
                s[t2, t, r] = pulp.LpVariable(f"s_{t2}_{t}_{r}", cat="Binary")

    # ---------------- Objective: weighted total delay ----------------
    prob += pulp.lpSum(
        priority_weights[t] * (a[t, routes[t][0]] - a0[t, routes[t][0]])
        for t in trains
    ), "Total_Weighted_Delay"

    # ---------------- Constraints ----------------
    for t in trains:
        route = routes[t]

        # (1) Time consistency: d = a + running time of chosen profile
        for r in route:
            prob += d[t, r] == a[t, r] + pulp.lpSum(
                running_times[t, r, p] * x[t, r, p] for p in profile_options[t]
            ), f"time_consistency_{t}_{r}"

            # (2) Exactly one speed profile per (t, r)
            prob += pulp.lpSum(x[t, r, p] for p in profile_options[t]) == 1, \
                f"profile_choice_{t}_{r}"

            # (9) Optional minimum dwell time
            md = min_dwell.get((t, r), 0)
            if md > 0:
                prob += d[t, r] >= a[t, r] + md, f"min_dwell_{t}_{r}"

        # (3) Route progression with DTG braking/approach time
        for r, r_next in zip(route, route[1:]):
            prob += a[t, r_next] >= d[t, r] + pulp.lpSum(
                braking_times[t, r_next, p] * x[t, r_next, p]
                for p in profile_options[t]
            ), f"route_progression_{t}_{r}_{r_next}"

        # (4) Initial delay at first resource
        r_first = route[0]
        prob += a[t, r_first] >= a0[t, r_first] + initial_delay[t], \
            f"initial_delay_{t}"

        # (5) Occupancy linking (big-M linearization)
        for r in route:
            for theta in times:
                # y = 1 iff a <= theta < d
                prob += y[t, r, theta] >= 1 - (a[t, r] - theta) / M, \
                    f"occ_lb1_{t}_{r}_{theta}"
                prob += y[t, r, theta] >= 1 - (theta - d[t, r] + 1) / M, \
                    f"occ_lb2_{t}_{r}_{theta}"
                prob += y[t, r, theta] <= 1 - (theta - d[t, r]) / M, \
                    f"occ_ub1_{t}_{r}_{theta}"
                prob += y[t, r, theta] <= 1 + (a[t, r] - theta) / M, \
                    f"occ_ub2_{t}_{r}_{theta}"

    # (6) Conflict detection
    for i, t in enumerate(trains):
        for t2 in trains[i + 1:]:
            shared = set(routes[t]) & set(routes[t2])
            for r in shared:
                for theta in times:
                    prob += z[t, t2, r, theta] >= \
                        y[t, r, theta] + y[t2, r, theta] - 1, \
                        f"conflict_{t}_{t2}_{r}_{theta}"

    # (7) & (8) Conflict resolution via ordering + headway on switches
    for i, t in enumerate(trains):
        for t2 in trains[i + 1:]:
            shared = set(routes[t]) & set(routes[t2])
            for r in shared:
                # exactly one ordering
                prob += s[t, t2, r] + s[t2, t, r] == 1, \
                    f"ordering_{t}_{t2}_{r}"
                # if s[t,t2,r]=1 then d_t <= a_t' (no overlap)
                prob += a[t2, r] >= d[t, r] - M * (1 - s[t, t2, r]), \
                    f"no_overlap_{t}_{t2}_{r}"
                prob += a[t, r] >= d[t2, r] - M * (1 - s[t2, t, r]), \
                    f"no_overlap_{t2}_{t}_{r}"
                # (8) switch headway
                if r in switch_resources:
                    h = headway.get(r, 0)
                    prob += a[t2, r] >= d[t, r] + h - M * (1 - s[t, t2, r]), \
                        f"headway_{t}_{t2}_{r}"
                    prob += a[t, r] >= d[t2, r] + h - M * (1 - s[t2, t, r]), \
                        f"headway_{t2}_{t}_{r}"

    return prob


# ---------------- Example usage ----------------
if __name__ == "__main__":
    trains = ["T1", "T2"]
    resources = ["R1", "R2", "R3"]
    switch_resources = ["R2"]
    routes = {"T1": ["R1", "R2", "R3"], "T2": ["R1", "R2", "R3"]}
    a0 = {("T1", "R1"): 0, ("T1", "R2"): 5, ("T1", "R3"): 10,
          ("T2", "R1"): 2, ("T2", "R2"): 7, ("T2", "R3"): 12}
    d0 = {("T1", "R1"): 5, ("T1", "R2"): 10, ("T1", "R3"): 15,
          ("T2", "R1"): 7, ("T2", "R2"): 12, ("T2", "R3"): 17}
    profile_options = {"T1": ["fast", "slow"], "T2": ["fast", "slow"]}
    running_times = {("T1", "R1", "fast"): 5, ("T1", "R1", "slow"): 6,
                     ("T1", "R2", "fast"): 5, ("T1", "R2", "slow"): 6,
                     ("T1", "R3", "fast"): 5, ("T1", "R3", "slow"): 6,
                     ("T2", "R1", "fast"): 5, ("T2", "R1", "slow"): 6,
                     ("T2", "R2", "fast"): 5, ("T2", "R2", "slow"): 6,
                     ("T2", "R3", "fast"): 5, ("T2", "R3", "slow"): 6}
    braking_times = {("T1", "R1", "fast"): 0, ("T1", "R1", "slow"): 0,
                     ("T1", "R2", "fast"): 1, ("T1", "R2", "slow"): 2,
                     ("T1", "R3", "fast"): 1, ("T1", "R3", "slow"): 2,
                     ("T2", "R1", "fast"): 0, ("T2", "R1", "slow"): 0,
                     ("T2", "R2", "fast"): 1, ("T2", "R2", "slow"): 2,
                     ("T2", "R3", "fast"): 1, ("T2", "R3", "slow"): 2}
    initial_delay = {"T1": 0, "T2": 3}
    priority_weights = {"T1": 1.0, "T2": 2.0}
    min_dwell = {}
    headway = {"R2": 1}
    H = 60

    model = build_cdr_milp(trains, resources, switch_resources, routes,
                           a0, d0, running_times, braking_times,
                           initial_delay, priority_weights, min_dwell,
                           headway, H, profile_options)
    model.solve(pulp.PULP_CBC_CMD(msg=1))

    print("Status:", pulp.LpStatus[model.status])
    print("Objective (weighted delay):", pulp.value(model.objective))
    for t in trains:
        for r in routes[t]:
            print(f"  {t} @ {r}: a={a0 and model.variables() and ''}"
                  f"{pulp.value(model.getVar(f'a_{t}_{r}')):.2f}, "
                  f"d={pulp.value(model.getVar(f'd_{t}_{r}')):.2f}")
```

**Notes on the implementation:**

- **Objective** minimizes the sum of entry delays at the first resource of each train, weighted by train priority `w_t`.
- **Constraint (3)** embeds the ETCS Level 2 DTG logic: the approach/braking time before entering the next resource depends on the selected speed profile (faster profiles → longer braking distances → earlier brake indication points).
- **Constraint (5)** uses big-M linearization of the occupancy indicator `y_{t,r,θ} = 1 ⟺ a ≤ θ < d`.
- **Constraints (7)–(8)** resolve conflicts via disjunctive ordering variables, with extra headway `h_r` on switch resources.
- Big-M is set to the horizon `H` as specified. For better numerical performance in practice, indicator constraints (solver-dependent) can replace the big-M formulations.

